32: #ifdef ARCH_X86
33: static inline uint32_t arch_accel (uint32_t accel)
34: {
35:     if (accel & (A52_ACCEL_X86_3DNOW | A52_ACCEL_X86_MMXEXT))
36: 	accel |= A52_ACCEL_X86_MMX;
37: 	
38:     if (accel & (A52_ACCEL_X86_SSE2 | A52_ACCEL_X86_SSE3))
39: 	accel |= A52_ACCEL_X86_MMXEXT;
40: 	
41:     if (accel & (A52_ACCEL_X86_SSE3))
42: 	accel |= A52_ACCEL_X86_SSE2;
43: 
44: #ifdef ACCEL_DETECT
45:     if (accel & A52_ACCEL_DETECT) {
46: 	uint32_t eax, ebx, ecx, edx;
47: 	int AMD;
48: 
49: #if defined(__x86_64__) || (!defined(PIC) && !defined(__PIC__))
50: #define cpuid(op,eax,ebx,ecx,edx)	\
51:     __asm__ ("cpuid"			\
52: 	     : "=a" (eax),		\
53: 	       "=b" (ebx),		\
54: 	       "=c" (ecx),		\
55: 	       "=d" (edx)		\
56: 	     : "a" (op)			\
57: 	     : "cc")
58: #else	/* PIC version : save ebx (not needed on x86_64) */
59: #define cpuid(op,eax,ebx,ecx,edx)	\
60:     __asm__ ("pushl %%ebx\n\t"		\
61: 	     "cpuid\n\t"		\
62: 	     "movl %%ebx,%1\n\t"	\
63: 	     "popl %%ebx"		\
64: 	     : "=a" (eax),		\
65: 	       "=r" (ebx),		\
66: 	       "=c" (ecx),		\
67: 	       "=d" (edx)		\
68: 	     : "a" (op)			\
69: 	     : "cc")
70: #endif
71: 
72: #ifndef __x86_64__ /* x86_64 supports the cpuid op */
73: 	__asm__ ("pushf\n\t"
74: 		 "pushf\n\t"
75: 		 "pop %0\n\t"
76: 		 "movl %0,%1\n\t"
77: 		 "xorl $0x200000,%0\n\t"
78: 		 "push %0\n\t"
79: 		 "popf\n\t"
80: 		 "pushf\n\t"
81: 		 "pop %0\n\t"
82: 		 "popf"
83: 		 : "=r" (eax),
84: 		 "=r" (ebx)
85: 		 :
86: 		 : "cc");
87: 
88: 	if (eax == ebx)			/* no cpuid */
89: 	    return accel;
90: #endif
91: 
92: 	cpuid (0x00000000, eax, ebx, ecx, edx);
93: 	if (!eax)			/* vendor string only */
94: 	    return accel;
95: 
96: 	AMD = (ebx == 0x68747541 && ecx == 0x444d4163 && edx == 0x69746e65);
97: 
98: 	cpuid (0x00000001, eax, ebx, ecx, edx);
99: 	if (! (edx & 0x00800000))	/* no MMX */
100: 	    return accel;
101: 
102: 	accel |= A52_ACCEL_X86_MMX;
103: 	if (edx & 0x02000000)		/* SSE - identical to AMD MMX ext. */
104: 	    accel |= A52_ACCEL_X86_MMXEXT;
105: 
106: 	if (edx & 0x04000000)		/* SSE2 */
107: 	    accel |= A52_ACCEL_X86_SSE2;
108: 
109: 	if (ecx & 0x00000001)		/* SSE3 */
110: 	    accel |= A52_ACCEL_X86_SSE3;
111: 
112: 	cpuid (0x80000000, eax, ebx, ecx, edx);
113: 	if (eax < 0x80000001)		/* no extended capabilities */
114: 	    return accel;
115: 
116: 	cpuid (0x80000001, eax, ebx, ecx, edx);
117: 
118: 	if (edx & 0x80000000)
119: 	    accel |= A52_ACCEL_X86_3DNOW;
120: 
121: 	if (AMD && (edx & 0x00400000))	/* AMD MMX extensions */
122: 	    accel |= A52_ACCEL_X86_MMXEXT;
123:     }
124: #endif /* ACCEL_DETECT */
125: 
126:     return accel;
127: }
128: #endif /* ARCH_X86 */
129: 
130: #if defined(ACCEL_DETECT) && (defined(ARCH_PPC) || defined(ARCH_SPARC))
131: #include <signal.h>
132: #include <setjmp.h>
133: 
134: static sigjmp_buf jmpbuf;
135: static volatile sig_atomic_t canjump = 0;
136: 
137: static RETSIGTYPE sigill_handler (int sig)
138: {
139:     if (!canjump) {
140: 	signal (sig, SIG_DFL);
141: 	raise (sig);
142:     }
143: 
144:     canjump = 0;
145:     siglongjmp (jmpbuf, 1);
146: }
147: #endif /* ACCEL_DETECT && (ARCH_PPC || ARCH_SPARC) */
148: 
149: #ifdef ARCH_PPC
150: static uint32_t arch_accel (uint32_t accel)
151: {
152: #ifdef ACCEL_DETECT
153:     if ((accel & (A52_ACCEL_PPC_ALTIVEC | A52_ACCEL_DETECT)) ==
154: 	A52_ACCEL_DETECT) {
155: 	static RETSIGTYPE (* oldsig) (int);
156: 
157: 	oldsig = signal (SIGILL, sigill_handler);
158: 	if (sigsetjmp (jmpbuf, 1)) {
159: 	    signal (SIGILL, oldsig);
160: 	    return accel;
161: 	}
162: 
163: 	canjump = 1;
164: 
165: #ifdef HAVE_ALTIVEC_H	/* gnu */
166: #define VAND(a,b,c) "vand " #a "," #b "," #c "\n\t"
167: #else			/* apple */
168: #define VAND(a,b,c) "vand v" #a ",v" #b ",v" #c "\n\t"
169: #endif
170: 	asm volatile ("mtspr 256, %0\n\t"
171: 		      VAND (0, 0, 0)
172: 		      :
173: 		      : "r" (-1));
174: 
175: 	canjump = 0;
176: 	accel |= A52_ACCEL_PPC_ALTIVEC;
177: 
178: 	signal (SIGILL, oldsig);
179:     }
180: #endif /* ACCEL_DETECT */
181: 
182:     return accel;
183: }
184: #endif /* ARCH_PPC */
185: 
186: #ifdef ARCH_SPARC
187: static uint32_t arch_accel (uint32_t accel)
188: {
189:     if (accel & A52_ACCEL_SPARC_VIS2)
190: 	accel |= A52_ACCEL_SPARC_VIS;
191: 
192: #ifdef ACCEL_DETECT
193:     if (accel & (A52_ACCEL_SPARC_VIS2 | A52_ACCEL_DETECT) ==
194: 	A52_ACCEL_DETECT) {
195: 	static RETSIGTYPE (* oldsig) (int);
196: 
197: 	oldsig = signal (SIGILL, sigill_handler);
198: 	if (sigsetjmp (jmpbuf, 1)) {
199: 	    signal (SIGILL, oldsig);
200: 	    return accel;
201: 	}
202: 
203: 	canjump = 1;
204: 
205: 	/* pdist %f0, %f0, %f0 */
206: 	__asm__ __volatile__(".word\t0x81b007c0");
207: 
208: 	canjump = 0;
209: 	accel |= A52_ACCEL_SPARC_VIS;
210: 
211: 	if (sigsetjmp (jmpbuf, 1)) {
212: 	    signal (SIGILL, oldsig);
213: 	    return accel;
214: 	}
215: 
216: 	canjump = 1;
217: 
218: 	/* edge8n %g0, %g0, %g0 */
219: 	__asm__ __volatile__(".word\t0x81b00020");
220: 
221: 	canjump = 0;
222: 	accel |= A52_ACCEL_SPARC_VIS2;
223: 
224: 	signal (SIGILL, oldsig);
225:     }
226: #endif /* ACCEL_DETECT */
227: 
228:     return accel;
229: }
230: #endif /* ARCH_SPARC */
231: 
232: #ifdef ARCH_ALPHA
233: static inline uint32_t arch_accel (uint32_t accel)
234: {
235:     if (accel & A52_ACCEL_ALPHA_MVI)
236: 	accel |= A52_ACCEL_ALPHA;
237: 
238: #ifdef ACCEL_DETECT
239:     if (accel & A52_ACCEL_DETECT) {
240: 	uint64_t no_mvi;
241: 
242: 	asm volatile ("amask %1, %0"
243: 		      : "=r" (no_mvi)
244: 		      : "rI" (256));	/* AMASK_MVI */
245: 	accel |= no_mvi ? A52_ACCEL_ALPHA : (A52_ACCEL_ALPHA |
246: 					       A52_ACCEL_ALPHA_MVI);
247:     }
248: #endif /* ACCEL_DETECT */
249: 
250:     return accel;
251: }
252: #endif /* ARCH_ALPHA */
253: 
254: uint32_t a52_detect_accel (uint32_t accel)
255: {
256: #if defined (ARCH_X86) || defined (ARCH_PPC) || defined (ARCH_ALPHA) || defined (ARCH_SPARC)
257:     accel = arch_accel (accel);
258: #endif
259:     return accel;
260: }

